-- 002: Teams voice call records; apply once after 001, or use runtime AutoMigrate.
CREATE TABLE `response_teams_voice_call` (`id` varchar(36),`dedup` varchar(64),`episode` varchar(160),`channel_id` bigint,`rule_id` bigint,`group_id` bigint,`recipient` varchar(320),`title` text,`state` varchar(24),`call_id` varchar(128),`answered_at` bigint,`play_state` varchar(24),`ended_at` bigint,`reason` text,`created_at` bigint,`expires_at` bigint,`fallback_queued` boolean,`close_requested` boolean,`audio_token` varchar(64),`payload` longtext,PRIMARY KEY (`id`),INDEX `idx_response_teams_voice_call_episode` (`episode`),INDEX `idx_response_teams_voice_call_expires_at` (`expires_at`),INDEX `idx_response_teams_voice_call_state` (`state`),UNIQUE INDEX `idx_response_teams_voice_call_dedup` (`dedup`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
